SELECT
    a.attendance_sq AS attendanceSq,
    a.user_sq AS userSq,
    a.attendance_dt AS attendanceDt,
    a.created_at_dtm AS createdAtDtm
FROM TBL_ATTENDANCE_M a
WHERE 1 = 1


    AND a.attendance_dt >= #{startDate}



    AND a.attendance_dt <= #{endDate}


ORDER BY a.created_at_dtm DESC
LIMIT #{size}
OFFSET #{offset}

SELECT
    COUNT(*)
FROM TBL_ATTENDANCE_M a
WHERE 1 = 1


    AND a.attendance_dt >= #{startDate}



    AND a.attendance_dt <= #{endDate}
